protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, null, 0, new ArrayList<>(), new ArrayList<>());
    }

    // Find a starting vertex
    V start = null;
    for (E edge : tour) {
        start = graph.getEdgeSource(edge);
        break;
    }

    // Build the path by following edges
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();

    V current = start;
    vertices.add(current);

    Set<E> remainingEdges = new HashSet<>(tour);

    while (!remainingEdges.isEmpty()) {
        // Find an edge from current vertex that is in the remaining set
        E nextEdge = null;
        for (E edge : remainingEdges) {
            if (graph.getEdgeSource(edge).equals(current) || graph.getEdgeTarget(edge).equals(current)) {
                nextEdge = edge;
                break;
            }
        }

        if (nextEdge == null) {
            // No edge found from current vertex, try to find any edge
            nextEdge = remainingEdges.iterator().next();
        }

        edges.add(nextEdge);
        remainingEdges.remove(nextEdge);

        // Determine the next vertex
        if (graph.getEdgeSource(nextEdge).equals(current)) {
            current = graph.getEdgeTarget(nextEdge);
        } else {
            current = graph.getEdgeSource(nextEdge);
        }

        vertices.add(current);
    }

    // Calculate the total weight
    double weight = 0;
    for (E edge : edges) {
        weight += graph.getEdgeWeight(edge);
    }

    return new GraphPathImpl<>(graph, start, current, weight, vertices, edges);
}

