public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder buf = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                buf.append(c);
                continue;
            }
            char next = str.charAt(i + 1);
            switch (next) {
                case 'n':
                    buf.append('\n');
                    i++;
                    break;
                case 't':
                    buf.append('\t');
                    i++;
                    break;
                case 'r':
                    buf.append('\r');
                    i++;
                    break;
                case 'f':
                    buf.append('\f');
                    i++;
                    break;
                case 'b':
                    buf.append('\b');
                    i++;
                    break;
                case '\\':
                    buf.append('\\');
                    i++;
                    break;
                case '\'':
                    buf.append('\'');
                    i++;
                    break;
                case '"':
                    buf.append('"');
                    i++;
                    break;
                case 'u':
                    if (i + 5 < len) {
                        String hex = str.substring(i + 2, i + 6);
                        try {
                            int codePoint = Integer.parseInt(hex, 16);
                            buf.append((char) codePoint);
                            i += 5;
                        } catch (NumberFormatException e) {
                            buf.append(c);
