static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        return timeBucket;
    }
    // Extract year, month, day from the timeBucket
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Calculate the first day of the month
    long firstDayOfMonth = year * 10000L + month * 100L + 1;

    // Calculate the number of days since the first day of the month
    int daysSinceFirst = day - 1;

    // Calculate the bucket index (0-based)
    int bucketIndex = daysSinceFirst / dayStep;

    // Calculate the start day of the bucket
    int startDay = bucketIndex * dayStep + 1;

    // Ensure startDay does not exceed the number of days in the month
    // We need to know the number of days in the month
    int daysInMonth;
    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            daysInMonth = 31;
            break;
        case 4: case 6: case 9: case 11:
            daysInMonth = 30;
            break;
        case 2:
            // Check for leap year
            if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
                daysInMonth = 29;
            } else {
                daysInMonth = 28;
            }
            break;
        default:
            daysInMonth = 30; // default
            break;
    }

    if (startDay > daysInMonth) {
        startDay = daysInMonth;
    }

    // Construct the compressed time bucket
    return year * 10000L + month * 100L + startDay;
}

