public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        return lb;
    }
    final int len = str.length();
    if (len == 0) {
        return lb;
    }
    final byte[] bytes = new byte[len * 3];
    int offset = 0;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            bytes[offset++] = (byte) c;
        } else if (c < 0x800) {
            bytes[offset++] = (byte) (0xC0 | (c >> 6));
            bytes[offset++] = (byte) (0x80 | (c & 0x3F));
        } else if (c < 0xD800 || c > 0xDFFF) {
            bytes[offset++] = (byte) (0xE0 | (c >> 12));
            bytes[offset++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            bytes[offset++] = (byte) (0x80 | (c & 0x3F));
        } else {
            // surrogate pair
            if (i + 1 < len) {
                char low = str.charAt(i + 1);
                if (low >= 0xDC00 && low <= 0xDFFF) {
                    int codePoint = 0x10000 + ((c - 0xD800) << 10) + (low - 0xDC00);
                    bytes[offset++] = (byte) (0xF0 | (codePoint >> 18));
                    bytes[offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
                    bytes[offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
                    bytes[offset++] = (byte) (0x80 | (codePoint & 0x3F));
                    i++;
                } else {
                    // invalid surrogate, write replacement character
                    bytes[offset++] = (byte) 0xEF;
                    bytes[offset++] = (byte) 0xBF;
                    bytes[offset++] = (byte) 0xBD;
                }
            } else {
                // unpaired surrogate, write replacement character
                bytes[offset++] = (byte) 0xEF;
                bytes[offset++] = (byte) 0xBF;
                bytes[offset++] = (byte) 0xBD;
            }
        }
    }
    final byte[] trimmed = new byte[offset];
    System.arraycopy(bytes, 0, trimmed, 0, offset);
    session.writeBytes(trimmed, 0, offset);
    return lb;
}

