public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    while (node != null) {
        byte[] data = node.getData();
        if (data != null) {
            out.write(data);
            totalSize += data.length;
        }
        node = node.getNext();
    }
    return totalSize;
}

