private void checkIfPackedField() throws IOException {
    if (fieldNumber == 0) {
        throw new IllegalStateException("Field number is 0, cannot check if packed.");
    }
    if (fieldNumber == 1) {
        // Check if the field is packed
        if (input.readTag() == WireFormat.makeTag(fieldNumber, WireFormat.WIRE_TYPE_LENGTH_DELIMITED)) {
            // Update internal state to reflect that packed fields are being read
            isPacked = true;
        }
    }
}

